"""Tests for depcycle.config module."""

from __future__ import annotations

from pathlib import Path

from depcycle.config import DEFAULT_EXCLUDE_PATTERNS, AnalysisConfig


def test_analysis_config_defaults(tmp_path: Path) -> None:
    config = AnalysisConfig(project_path=tmp_path)
    assert config.project_path == tmp_path
    assert config.show_third_party is True
    assert config.show_stdlib is True
    assert config.show_unknown is True
    assert config.include_all is False
    assert config.fail_on_cycles is False
    assert config.targets == []
    for default_pat in DEFAULT_EXCLUDE_PATTERNS:
        assert default_pat in config.exclude_patterns


def test_analysis_config_include_all(tmp_path: Path) -> None:
    config = AnalysisConfig(
        project_path=tmp_path,
        exclude_patterns=["custom_dir"],
        include_all=True,
    )
    assert config.exclude_patterns == ["custom_dir"]


def test_from_pyproject_without_file(tmp_path: Path) -> None:
    config = AnalysisConfig.from_pyproject(
        project_path=tmp_path,
        cli_exclude=["custom_exclude"],
        cli_show_third_party=False,
        cli_show_stdlib=False,
        include_all=False,
        fail_on_cycles=True,
    )
    assert config.show_third_party is False
    assert config.show_stdlib is False
    assert config.fail_on_cycles is True
    assert "custom_exclude" in config.exclude_patterns


def test_from_pyproject_with_valid_toml(tmp_path: Path) -> None:
    pyproject = tmp_path / "pyproject.toml"
    pyproject.write_text(
        """
[tool.depcycle]
exclude = ["toml_exclude"]
show_third_party = false
show_stdlib = false
fail_on_cycles = true
""",
        encoding="utf-8",
    )

    config = AnalysisConfig.from_pyproject(
        project_path=tmp_path,
        cli_exclude=["cli_exclude"],
        cli_show_third_party=True,
        cli_show_stdlib=True,
        fail_on_cycles=False,
    )
    # cli_show_third_party (True) and toml (False) -> False
    assert config.show_third_party is False
    assert config.show_stdlib is False
    # fail_on_cycles cli (False) or toml (True) -> True
    assert config.fail_on_cycles is True
    assert "toml_exclude" in config.exclude_patterns
    assert "cli_exclude" in config.exclude_patterns


def test_from_pyproject_with_invalid_toml(tmp_path: Path) -> None:
    pyproject = tmp_path / "pyproject.toml"
    pyproject.write_text("invalid toml [syntax", encoding="utf-8")

    config = AnalysisConfig.from_pyproject(project_path=tmp_path)
    assert config.project_path == tmp_path
